// Category consolidation (July 2026): merged 6 → 3 for cleaner UX.
// Old fun → playful. Old romantic + therapy → deep. Old fantasy → spicy.
// Existing questions get remapped inline below in the QUESTIONS array.
export type QuestionCategory = 'playful' | 'deep' | 'spicy';

export type QuestionFormat = 'open' | 'binary' | 'scale';

export interface Question {
  text: string;
  category: QuestionCategory;
  tags?: string[]; // e.g. ['ldr'] — used to mix LDR-flavored questions into existing categories
  format?: QuestionFormat; // undefined means 'open' (legacy text answer)
  options?: [string, string]; // required when format === 'binary'
}

