// ─── DARE WHEEL ───────────────────────────────────────────────────────────────

export type DareLevel = 'sweet' | 'flirty' | 'spicy';

// Aug 2026: 3-way context classification for the LDR filter. Replaces
// the earlier boolean `remote?: true`.
//   'ldr'       — LDR-only. Feels weird in-person (video call, sexting,
//                 photo of body part partner could just see, camera
//                 performance, voice memo of live-audible sounds).
//   'either'    — Hybrid. Produces a lasting artifact or coordinated
//                 moment that has value regardless of proximity (song
//                 send, playlist, coordinated candle ritual, cooked
//                 meal + photo, handwritten letter, mailed note, "in
//                 front of {partner}" phrasings that work live or on
//                 camera).
//   'physical'  — In-person only, requires proximity (kiss, touch,
//                 oral, positions, hug, foot massage, feed). This is
//                 the implicit default when `context` is undefined so
//                 the historical majority-physical pool needs no
//                 migration marker.
// Filter in `app/truth-dare.tsx`:
//   isLDR on  → DARES.filter(d => d.context === 'ldr' || d.context === 'either')
//   isLDR off → DARES.filter(d => d.context !== 'ldr')
// Both modes see 'either'. Only 'ldr' is exclusive to the LDR view;
// only 'physical' (or undefined) is exclusive to the in-person view.
export type DareContext = 'ldr' | 'either' | 'physical';

export interface Dare {
  text: string;
  level: DareLevel;
  context?: DareContext;
}

